import { useState, useCallback } from 'react';
import { JxCalendar, JxButton } from '@jinx-ui/react';

interface ReportDatePickerProps {
  value?: Date | null;
  onChange?: (date: Date | null) => void;
}

function startOfDay(date: Date): Date {
  const d = new Date(date);
  d.setHours(0, 0, 0, 0);
  return d;
}

function addDays(date: Date, days: number): Date {
  const d = new Date(date);
  d.setDate(d.getDate() + days);
  return d;
}

export default function ReportDatePicker({ value, onChange }: ReportDatePickerProps) {
  const [internalValue, setInternalValue] = useState<Date | null>(value ?? null);
  const selected = value !== undefined ? value : internalValue;

  const applyDate = useCallback(
    (date: Date | null) => {
      if (value === undefined) {
        setInternalValue(date);
      }
      onChange?.(date);
    },
    [value, onChange]
  );

  const today = startOfDay(new Date());
  const yesterday = addDays(today, -1);
  const weekAgo = addDays(today, -7);

  const isSameDay = (a: Date | null, b: Date) =>
    !!a && a.getFullYear() === b.getFullYear() && a.getMonth() === b.getMonth() && a.getDate() === b.getDate();

  const quickOptions: { label: string; date: Date }[] = [
    { label: 'Сегодня', date: today },
    { label: 'Вчера', date: yesterday },
    { label: 'Неделя назад', date: weekAgo },
  ];

  return (
    <div style={{ display: 'flex', flexDirection: 'column', gap: 12 }}>
      <div
        role="group"
        aria-label="Быстрый выбор даты"
        style={{ display: 'flex', gap: 8, flexWrap: 'wrap' }}
      >
        {quickOptions.map((option) => (
          <JxButton
            key={option.label}
            type="button"
            size="sm"
            variant={isSameDay(selected, option.date) ? 'primary' : 'outline'}
            onClick={() => applyDate(option.date)}
          >
            {option.label}
          </JxButton>
        ))}
      </div>
      <JxCalendar locale="ru-RU" value={selected} onValueChange={applyDate} />
    </div>
  );
}

